"use client";

import { useEffect, useState } from "react";
import { CrdForm } from "./CrdForm";
import type { CrdChoices } from "./choices";
import { isCrdIndex, type CrdIndexEntry } from "./types";
import { fetchJson } from "./fetch-json";

// A single entry point to every per-CRD form: pick a kind, and the same
// <CrdForm> the individual CRD pages embed renders below. The kind list comes
// from crd-schemas/index.json, generated by `weebo-crd-docs` alongside the
// per-kind schemas — no hand-maintained list to drift.
export function CrdBuilder({ choices }: { choices?: CrdChoices | undefined }) {
  const [kinds, setKinds] = useState<CrdIndexEntry[] | null>(null);
  const [selected, setSelected] = useState<string>("");
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const controller = new AbortController();
    fetchJson("/crd-schemas/index.json", isCrdIndex, controller.signal)
      .then((index) => {
        // A schematic kind is the IDE's only: no manifest to build.
        const data = index.filter((k) => !k.schematic);
        setKinds(data);
        setSelected(data[0]?.kind ?? "");
      })
      .catch((err: unknown) => {
        if (!controller.signal.aborted) setError(err instanceof Error ? err.message : String(err));
      });
    return () => controller.abort();
  }, []);

  if (error) {
    return (
      <p className="border border-(--rule-strong) px-6 py-10 text-[13px] text-fd-muted-foreground">
        Could not load the CRD list: {error}
      </p>
    );
  }

  if (!kinds) {
    return (
      <p className="border border-(--rule-strong) px-6 py-10 text-[13px] text-fd-muted-foreground">
        Loading CRDs...
      </p>
    );
  }

  return (
    <div className="flex flex-col gap-5">
      <div className="flex flex-col gap-1">
        <label
          htmlFor="crd-kind"
          className="text-[12px] font-semibold uppercase tracking-[0.14em] text-fd-muted-foreground"
        >
          Resource kind
        </label>
        <select
          id="crd-kind"
          className="w-full max-w-xs border border-(--rule-strong) bg-(--ground-sunk) px-3 py-2 text-[15px] text-fd-foreground focus:border-(--accent) sm:max-w-sm"
          value={selected}
          onChange={(e) => setSelected(e.target.value)}
        >
          {kinds.map((entry) => (
            <option key={entry.kind} value={entry.kind}>
              {entry.kind} ({entry.scope})
            </option>
          ))}
        </select>
      </div>

      {selected ? <CrdForm key={selected} kind={selected} choices={choices?.[selected]} /> : null}
    </div>
  );
}
